import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        char[][] board = new char[3][3];
        for (char[] row : board) {
            Arrays.fill(row, '.');
        }
        char player = 'X';
        try (Scanner sc = new Scanner(System.in)) {
            while (sc.hasNextInt()) {
                int row = sc.nextInt();
                int col = sc.nextInt();
                try {
                    place(board, row, col, player);
                    System.out.println(player + " at " + row + " " + col);
                    player = player == 'X' ? 'O' : 'X';
                } catch (InvalidMoveException e) {
                    System.out.println("Invalid move: " + e.getMessage());
                }
            }
        }
        printBoard(board);
    }

    static void place(char[][] board, int row, int col, char mark) throws InvalidMoveException {
        if (row < 0 || row > 2 || col < 0 || col > 2) {
            throw new InvalidMoveException("Square " + row + " " + col + " is off the board");
        }
        if (board[row][col] != '.') {
            throw new InvalidMoveException("Square " + row + " " + col + " is taken");
        }
        board[row][col] = mark;
    }

    static void printBoard(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                System.out.print(cell);
            }
            System.out.println();
        }
    }
}

class InvalidMoveException extends Exception {
    InvalidMoveException(String message) {
        super(message);
    }
}
